<?php use VazinCMS\{Security,SiteBrand,VazinIdClient};$brand=SiteBrand::name();?><section class="auth"><div class="logo"><?=Security::e(mb_strtoupper(mb_substr($brand,0,1)))?></div><h1>ورود به مدیریت <?=Security::e($brand)?></h1><?php if($error):?><div class="alert"><?=Security::e($error)?></div><?php endif;?><?php if(VazinIdClient::configured()):?><p><a class="button primary" href="/auth/vazin-id/start">ورود امن به حساب</a></p><?php endif;?><details><summary>ورود مدیر اصلی</summary><form method="post"><input type="hidden" name="_csrf" value="<?=Security::e(Security::csrf())?>"><label>ایمیل مدیر اصلی<input type="email" name="email" required autocomplete="username"></label><label>رمز عبور<input type="password" name="password" required autocomplete="current-password"></label><button>ورود</button></form></details></section>
